import resonance.db as db
import resonance.si as si
from resonance.internal import declare_transformation, Processor

## СОЗДАНО ЧАТОМ БЕЗ ИЗМЕНЕНИЙ


@declare_transformation
class cross_combine_events(Processor):
    """
    Позиционно комбинирует несколько входных потоков событий:
    для каждого индекса i берёт i-е элементы из всех входов,
    формирует кортеж полезных нагрузок и создаёт событие с TS из первого входа.
    """
    def __init__(self):
        self._si = None
        self._captures = None  # список накопителей для каждого входа

    def prepare(self, *inputs: db.Event):
        if len(inputs) == 0:
            raise Exception("Нужен минимум один входной поток событий")
        for idx, inp in enumerate(inputs):
            if not isinstance(inp, db.Event):
                raise Exception(f"Тип входа #{idx+1} должен быть db.Event")

        self._si = si.Event()
        # Создаём пустые накопители под каждую входную SI
        self._captures = [db.make_empty(inp.SI) for inp in inputs]
        return self._si

    def online(self, *inputs: db.Event):
        # Обновляем накопители новыми порциями событий
        for k, inp in enumerate(inputs):
            self._captures[k] = db.combine(self._captures[k], inp)

        # Сколько синхронных позиций доступно во всех входах (как mapply/zip до минимальной длины)
        available = [len(cap.TS) for cap in self._captures]
        n = min(available) if available else 0
        if n == 0:
            # Нечего выдавать сейчас
            return db.make_empty(self._si)

        first_ts = self._captures[0].TS
        result = []

        # Формируем события позиционно
        for i in range(n):
            payload = tuple(cap[i] for cap in self._captures)  # аналог ret <- list(...)
            ts = first_ts[i]  # attr(ret, 'TS') <- attr(ret[[1]], 'TS')
            ev = db.Event(self._si, ts, payload)
            result.append(ev)

        # Обрезаем уже использованные элементы из накопителей
        self._captures = [cap[n:] for cap in self._captures]

        return db.combine(*result, si=self._si)